+/// Returns `montgomery_mul(a, 2^exponent)` for `exponent < 256`, forming the
+/// product by a shift instead of a multiplication.
+#[inline(always)]
+fn montgomery_mul_pow2(a: [u64; 4], exponent: u32) -> [u64; 4] {
+    let offset = (exponent / 64) as usize;
+    let bit = exponent % 64;
+    let mut wide = [0u64; 8];
+    for i in 0..4 {
+        wide[offset + i] |= a[i] << bit;
+        if bit > 0 {
+            wide[offset + i + 1] |= a[i] >> (64 - bit);
+        }
+    }
+    montgomery_reduce(wide)
+}
